void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 正規化されたピクセル座標を取得 (0.0 - 1.0)
    vec2 uv = fragCoord/iResolution.xy;

    // 中心を(0,0)にする
    vec2 center = uv - 0.5;

    // 中心からの距離を計算
    float dist = length(center);

    // 時間に基づいて波紋を作成
    float wave = sin(dist * 50.0 - iTime * 2.0) * 0.5 + 0.5;

    // 色を生成
    vec3 color = vec3(wave);

    // 距離に応じて色相を変化させる
    color.r *= sin(iTime) * 0.5 + 0.5;
    color.b *= cos(iTime) * 0.5 + 0.5;

    // 最終的な色を設定
    fragColor = vec4(color, 1.0);
}
